/**
 * Mengambil artikel berdasarkan slug
 */
export function getArticleBySlug(slug: string): NewsArticle | undefined {
  return staticArticles.find((art) => art.slug === slug);
}

/**
 * Mengambil seluruh artikel yang dijamin terurut dari tanggal rilis terakhir (terbaru ke terlama)
 */
export function getAllArticles(): NewsArticle[] {
  return [...staticArticles].sort((a, b) => {
    return new Date(b.publishedDate).getTime() - new Date(a.publishedDate).getTime();
  });
}

export function getUpcomingEvents(): CampusEvent[] {
  return staticEvents;
}
